type OrderCreateFields = {
  "kind": "commercial" | "support"
  "items": Array<OrderItemInput>
  "contact": Contact
  "organization_name"?: (string | null)
  "city"?: (string | null)
  "comment"?: (string | null)
  "source": "site" | "chat"
  "chat_session_id"?: (UUID | null)
  "consent": ConsentAcceptance
  "confirmed": true
}

export type OrderCreate = Omit<OrderCreateFields,
  "kind" | "items" | "comment" | "source" | "chat_session_id"> & (
    { kind: "commercial"; items: [OrderItemInput, ...OrderItemInput[]];
      comment?: string | null }
    | { kind: "support"; items: []; comment: string }
  ) & (
    { source: "site"; chat_session_id?: never }
    | { source: "chat"; chat_session_id: UUID }
  )

export type OrderHeaders = {
  "Idempotency-Key": UUID
  "X-Request-Token": SecretToken
}

